 50	    /**
 51	     * Randomly populate the field with foxes and rabbits.
 52	     */
 53	    public void populate(List<Entity> organisms, Field field)
 54	    {
 55	        Random rand = Randomizer.getRandom();
 56	        field.clear();
 57	        for(int row = 0; row < field.getDepth(); row++) {
 58	            for(int col = 0; col < field.getWidth(); col++) {
 59	                if (maybeAddOrganism(rand, organisms, field, row, col, LION_CREATION_PROBABILITY,
 60	                        (currentField, location) -> new Lion(19, true, currentField, location))) {
 61	                    continue;
 62	                }
 63	                if (maybeAddOrganism(rand, organisms, field, row, col, ZEBRA_CREATION_PROBABILITY,
 64	                        (currentField, location) -> new Zebra(5, true, currentField, location))) {
 65	                    continue;
 66	                }
 67	                if (maybeAddOrganism(rand, organisms, field, row, col, VULTURE_CREATION_PROBABILITY,
 68	                        (currentField, location) -> new Vulture(40, true, currentField, location))) {
 69	                    continue;
 70	                }
 71	                if (maybeAddOrganism(rand, organisms, field, row, col, GRASS_CREATION_PROBABILITY,
 72	                        (currentField, location) -> new Grass(1, 1, true, currentField, location))) {
 73	                    continue;
 74	                }
 75	                if (maybeAddOrganism(rand, organisms, field, row, col, GOAT_CREATION_PROBABILITY,
 76	                        (currentField, location) -> new Goat(5, true, currentField, location))) {
 77	                    continue;
 78	                }
 79	                if (maybeAddOrganism(rand, organisms, field, row, col, ELEPHANT_CREATION_PROBABILITY,
 80	                        (currentField, location) -> new Elephant(5, true, currentField, location))) {
 81	                    continue;
 82	                }
 83	                if (maybeAddOrganism(rand, organisms, field, row, col, CHEETAH_CREATION_PROBABILITY,
 84	                        (currentField, location) -> new Cheetah(19, true, currentField, location))) {
 85	                    continue;
 86	                }
 87	                maybeAddOrganism(rand, organisms, field, row, col, POISON_BERRIES_CREATION_PROBABILITY,
 88	                        (currentField, location) -> new PoisonBerry(2, 1, true, currentField, location));
 89	                // else leave the location empty.
 90	            }
 91	        }
 92	    }
 93	
 94	    /**
 95	     * Add a single organism to the requested location when the probability check passes.
 96	     *
 97	     * @return true if an organism was created and added.
 98	     */
 99	    private boolean maybeAddOrganism(Random rand, List<Entity> organisms, Field field, int row, int col,
100	                                     double probability, BiFunction<Field, Location, Entity> creator) {
101	        if (rand.nextDouble() <= probability) {
102	            organisms.add(creator.apply(field, new Location(row, col)));
103	            return true;
104	        }
105	        return false;
106	    }
107	}

 80	    public void simulate(int numSteps)
 81	    {
 82	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
 83	            simulateOneStep();
 84	            delay(5);   // uncomment this to run more slowly
 85	        }
 86	    }
