     4	/**
     5	 * This class collects and provides some statistical data on the state 
     6	 * of a field. It is flexible: it will create and maintain a counter 
     7	 * for any class of object that is found within the field.
     8	 *
     9	 * @version 2016.02.29
    10	 */
    11	public class FieldStats
    12	{
    13	    // Counters for each type of entity (fox, rabbit, etc.) in the simulation.
    14	    private Map<Class<?>, Counter> counters;
    15	    // Whether the counters are currently up to date.
    16	    private boolean countsValid;
    17	
    18	    /**
    19	     * Construct a FieldStats object.
    20	     */
    21	    public FieldStats()
    22	    {
    23	        // Set up a collection for counters for each type of animal that
    24	        // we might find
    25	        counters = new HashMap<>();
    26	        countsValid = true;
    27	    }
    28	
    29	    /**
    30	     * Get details of what is in the field.
    31	     * @return A string describing what is in the field.
    32	     */
    33	    public String getPopulationDetails(Field field)
    34	    {
    35	        StringBuilder buffer = new StringBuilder();
    36	        if(!countsValid) {
    37	            generateCounts(field);
    38	        }
    39	        for (Counter info : counters.values()) {
    40	            buffer.append(info.getName());
    41	            buffer.append(": ");
    42	            buffer.append(info.getCount());
    43	            buffer.append(' ');
    44	        }
    45	        return buffer.toString();
    46	    }
    47	    
    48	    /**
    49	     * Invalidate the current set of statistics; reset all 
    50	     * counts to zero.
    51	     */
    52	    public void reset()
    53	    {
    54	        countsValid = false;
    55	        for (Counter count : counters.values()) {
    56	            count.reset();
    57	        }
    58	    }
    59	
    60	    /**
    61	     * Increment the count for one class of animal.
    62	     * @param animalClass The class of animal to increment.
    63	     */
    64	    public void incrementCount(Class<?> animalClass)
    65	    {
    66	        Counter count = counters.get(animalClass);
    67	        if(count == null) {
    68	            // We do not have a counter for this species yet.
    69	            // Create one.
    70	            count = new Counter(animalClass.getName());
    71	            counters.put(animalClass, count);
    72	        }
    73	        count.increment();
    74	    }
    75	
    76	    /**
    77	     * Indicate that an animal count has been completed.
    78	     */
    79	    public void countFinished()
    80	    {
    81	        countsValid = true;
    82	    }
    83	
    84	    /**
    85	     * Determine whether the simulation is still viable.
    86	     * I.e., should it continue to run.
    87	     * @return true If there is more than one species alive.
    88	     */
    89	    public boolean isViable(Field field)
    90	    {
    91	        // How many counts are non-zero.
    92	        int nonZero = 0;
    93	        if(!countsValid) {
    94	            generateCounts(field);
    95	        }
    96	        for (Counter info : counters.values()) {
    97	            if(info.getCount() > 0) {
    98	                nonZero++;
    99	            }
   100	        }
   101	        return nonZero > 1;
   102	    }
   103	    
   104	    /**
   105	     * Generate counts of the number of foxes and rabbits.
   106	     * These are not kept up to date as foxes and rabbits
   107	     * are placed in the field, but only when a request
   108	     * is made for the information.
   109	     * @param field The field to generate the stats for.
   110	     */
   111	    private void generateCounts(Field field)
   112	    {
   113	        reset();
   114	        for(int row = 0; row < field.getDepth(); row++) {
   115	            for(int col = 0; col < field.getWidth(); col++) {
   116	                Object animal = field.getObjectAt(row, col);
   117	                if(animal != null) {
   118	                    incrementCount(animal.getClass());
   119	                }
   120	            }
   121	        }
   122	        countsValid = true;
   123	    }
   124	}

